(function(){
  'use strict';
  const view=()=>document.getElementById('admin-secondary-view');
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const roles=['COLABORADOR','AGENTE_SERVICO','GESTOR_APROVADOR','ADMINISTRADOR'];
  const scopes=[['viagem','Viagens'],['mobilidade','Mobilidade'],['transporte','Transportes'],['estacionamento','Estacionamento'],['entregas','Entregas'],['correios','Correios'],['xerox','Xerox / Impressões'],['achados_perdidos','Achados e Perdidos'],['liberacao_acesso','Acessos'],['autorizacao_excepcional','Autorizações Excepcionais'],['investigacao_ocorrencia','Investigação de Ocorrência']];
  let users=[],audit=[];
  const fmt=v=>v?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'Nunca';
  const shell=(title,subtitle,actions='')=>`<header class="admin-header"><div><p class="admin-governance-eyebrow">Administração Central 360</p><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p></div><div class="admin-header-meta">${actions}<span class="demo-badge">Dados demonstrativos</span></div></header>`;
  function error(message){view().innerHTML=shell('Administração indisponível','Não foi possível carregar esta área.')+`<div class="alert-box alert-danger">${esc(message)}</div>`;}
  function userScope(u){if(u.role==='ADMINISTRADOR')return'ALL';if(u.role==='GESTOR_APROVADOR')return(u.approvalScopes||[]).join(' · ')||'Alçada demonstrativa';return(u.serviceScopes||[]).map(id=>scopes.find(x=>x[0]===id)?.[1]||id).join(' · ')||'—';}
  function renderUsers(){const demo=users.filter(u=>u.id.startsWith('USR-DEMO-'));const counts=Object.fromEntries(roles.map(r=>[r,demo.filter(u=>u.role===r&&u.accessStatus==='ATIVO').length]));view().innerHTML=shell('Usuários & Permissões','Gerencie acesso à ferramenta, perfis e escopos. Dados corporativos permanecem somente leitura.','<button class="btn btn-primary" id="admin-add-user">Adicionar usuário</button>')+`
    <section class="admin-user-kpis"><div><span>Usuários ativos</span><strong>${demo.filter(u=>u.accessStatus==='ATIVO').length}</strong></div><div><span>Agentes de Serviço</span><strong>${counts.AGENTE_SERVICO}</strong></div><div><span>Gestores Aprovadores</span><strong>${counts.GESTOR_APROVADOR}</strong></div><div><span>Administradores</span><strong>${counts.ADMINISTRADOR}</strong></div><div><span>Acessos desativados</span><strong>${demo.filter(u=>u.accessStatus==='DESATIVADO').length}</strong></div></section>
    <section class="panel"><div class="admin-user-filters"><label>Buscar<input id="user-search" placeholder="Nome, matrícula, e-mail ou área"></label><label>Perfil<select id="user-role"><option value="">Todos</option>${roles.map(r=>`<option>${r}</option>`).join('')}</select></label><label>Status<select id="user-status"><option value="">Todos</option><option>ATIVO</option><option>DESATIVADO</option></select></label><label>Vertical<select id="user-scope"><option value="">Todas</option>${scopes.map(s=>`<option value="${s[0]}">${s[1]}</option>`).join('')}</select></label></div><div class="admin-users-table-wrap"><table class="data-table admin-users-table"><thead><tr><th>Usuário</th><th>Matrícula</th><th>Área</th><th>Perfil Central 360</th><th>Escopo</th><th>Status</th><th>Último acesso</th><th>Ações</th></tr></thead><tbody id="admin-users-body"></tbody></table><div id="admin-users-empty" class="audit-empty" hidden>Nenhum usuário encontrado.</div></div></section><div id="admin-governance-modal"></div>`;
    const draw=()=>{const q=document.getElementById('user-search').value.toLowerCase(),role=document.getElementById('user-role').value,status=document.getElementById('user-status').value,scope=document.getElementById('user-scope').value;const filtered=demo.filter(u=>(!q||[u.name,u.employeeId,u.email,u.department].some(x=>String(x).toLowerCase().includes(q)))&&(!role||u.role===role)&&(!status||u.accessStatus===status)&&(!scope||(u.serviceScopes||[]).includes(scope)));const body=document.getElementById('admin-users-body');body.innerHTML=filtered.map(u=>`<tr><td><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></td><td>${esc(u.employeeId)}</td><td>${esc(u.department)}</td><td><span class="soft-badge">${esc(u.role)}</span></td><td class="admin-scope-cell">${esc(userScope(u))}</td><td><span class="status-chip ${u.accessStatus==='DESATIVADO'?'attention':''}">${esc(u.accessStatus)}</span></td><td>${esc(fmt(u.lastAccessAt))}</td><td><button class="btn btn-secondary btn-sm" data-manage="${esc(u.id)}">Gerenciar permissões</button></td></tr>`).join('');document.getElementById('admin-users-empty').hidden=filtered.length>0;body.querySelectorAll('[data-manage]').forEach(b=>b.addEventListener('click',()=>openUser(b.dataset.manage)));};
    ['user-search','user-role','user-status','user-scope'].forEach(id=>document.getElementById(id).addEventListener(id==='user-search'?'input':'change',draw));document.getElementById('admin-add-user').addEventListener('click',openAdd);draw();
  }
  function modal(markup){const host=document.getElementById('admin-governance-modal');host.innerHTML=`<div class="modal-overlay active admin-governance-overlay"><div class="modal-container admin-permission-modal" role="dialog" aria-modal="true">${markup}</div></div>`;host.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>host.innerHTML=''));host.querySelector('.modal-overlay').addEventListener('click',e=>{if(e.target===e.currentTarget)host.innerHTML=''});}
  function permissionFields(u){return `<section class="admin-permission-section"><h3>Permissões na Central 360</h3><label>Perfil Central 360<select id="permission-role">${roles.map(r=>`<option ${u.role===r?'selected':''}>${r}</option>`).join('')}</select></label><div id="permission-role-fields"></div><p class="admin-role-note" id="permission-role-note"></p></section>`;}
  function updateRoleFields(u){const role=document.getElementById('permission-role').value,box=document.getElementById('permission-role-fields'),note=document.getElementById('permission-role-note');note.textContent=role==='ADMINISTRADOR'?'Este perfil concede acesso administrativo amplo à Central 360.':role==='COLABORADOR'?'Colaborador não possui serviceScopes operacionais.':'';if(role==='AGENTE_SERVICO')box.innerHTML=`<fieldset><legend>Verticais sob responsabilidade</legend><div class="admin-scope-grid">${scopes.map(([id,label])=>`<label><input type="checkbox" name="scope" value="${id}" ${(u.serviceScopes||[]).includes(id)?'checked':''}> ${label}</label>`).join('')}</div></fieldset>`;else if(role==='GESTOR_APROVADOR')box.innerHTML=`<label>Escopo de aprovação demonstrativo<textarea id="approval-scopes">${esc((u.approvalScopes||['DEMO_ALL']).join('\n'))}</textarea></label><p class="admin-demo-warning">Configuração demonstrativa — pendente de integração e validação institucional.</p>`;else box.innerHTML='';}
  function openUser(id){const u=users.find(x=>x.id===id);modal(`<div class="modal-header"><div><h2 class="modal-title">Gerenciar permissões</h2><p>${esc(u.name)}</p></div><button class="btn-icon" data-close>×</button></div><div class="admin-permission-body"><section class="admin-permission-section"><h3>Dados corporativos</h3><p class="admin-source-note">Origem: Perfil corporativo / SAP RH futuro · somente leitura</p><div class="admin-readonly-grid">${[['Nome',u.name],['Matrícula',u.employeeId],['E-mail',u.email],['Cargo',u.jobTitle],['Área',u.department],['Centro de custo',u.costCenter],['Gestor',u.manager]].map(x=>`<label>${x[0]}<input value="${esc(x[1])}" readonly></label>`).join('')}</div></section>${permissionFields(u)}<section class="admin-permission-section"><h3>Status de acesso</h3><p>Desativar bloqueia acessos futuros sem excluir perfil, solicitações ou auditoria.</p><button class="btn ${u.accessStatus==='ATIVO'?'btn-danger':'btn-secondary'}" id="toggle-access">${u.accessStatus==='ATIVO'?'Desativar acesso à Central 360':'Reativar acesso'}</button></section></div><div class="modal-footer"><button class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary" id="save-permissions">Salvar permissões</button></div>`);updateRoleFields(u);document.getElementById('permission-role').addEventListener('change',()=>updateRoleFields({...u,serviceScopes:[],approvalScopes:[]}));document.getElementById('save-permissions').addEventListener('click',async()=>{const role=document.getElementById('permission-role').value;if(role==='ADMINISTRADOR'&&u.role!=='ADMINISTRADOR'&&!confirm('Este perfil concede acesso administrativo amplo à Central 360. Confirmar alteração?'))return;const serviceScopes=[...document.querySelectorAll('[name="scope"]:checked')].map(x=>x.value),approvalScopes=(document.getElementById('approval-scopes')?.value||'').split(/\n|,/).map(x=>x.trim()).filter(Boolean);await CS360API.updateAdminUserPermissions(u.id,{role,serviceScopes,approvalScopes});await loadUsers();document.getElementById('admin-governance-modal').innerHTML='';renderUsers();});document.getElementById('toggle-access').addEventListener('click',async()=>{const next=u.accessStatus==='ATIVO'?'DESATIVADO':'ATIVO';if(!confirm(next==='DESATIVADO'?'Desativar acesso sem excluir histórico ou solicitações?':'Reativar acesso à Central 360?'))return;await CS360API.updateAdminUserAccess(u.id,{accessStatus:next});await loadUsers();document.getElementById('admin-governance-modal').innerHTML='';renderUsers();});}
  function openAdd(){const u={role:'COLABORADOR',serviceScopes:[],approvalScopes:[]};modal(`<form id="add-user-form"><div class="modal-header"><div><h2 class="modal-title">Adicionar usuário</h2><p>Cadastro demonstrativo · futuro provisionamento por SAP RH / SSO.</p></div><button type="button" class="btn-icon" data-close>×</button></div><div class="admin-permission-body"><div class="admin-readonly-grid"><label>Matrícula demo<input id="add-employee" required placeholder="MAT-DEMO-05"></label><label>Nome demo<input id="add-name" required placeholder="Usuário Demo"></label><label>E-mail demo<input id="add-email" type="email" required placeholder="usuario.demo@hospital-demo.org"></label><label>Status<select id="add-status"><option>ATIVO</option><option>DESATIVADO</option></select></label></div>${permissionFields(u)}</div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary">Adicionar usuário</button></div></form>`);updateRoleFields(u);document.getElementById('permission-role').addEventListener('change',()=>updateRoleFields(u));document.getElementById('add-user-form').addEventListener('submit',async e=>{e.preventDefault();const role=document.getElementById('permission-role').value;if(role==='ADMINISTRADOR'&&!confirm('Este perfil concede acesso administrativo amplo à Central 360. Confirmar cadastro?'))return;await CS360API.createAdminUser({employeeId:document.getElementById('add-employee').value,name:document.getElementById('add-name').value,email:document.getElementById('add-email').value,role,accessStatus:document.getElementById('add-status').value,serviceScopes:[...document.querySelectorAll('[name="scope"]:checked')].map(x=>x.value)});await loadUsers();document.getElementById('admin-governance-modal').innerHTML='';renderUsers();});}
  function renderAudit(){view().innerHTML=shell('Auditoria','Quem fez o quê, quando e sobre qual recurso. Eventos são somente leitura.')+`<section class="panel"><div class="admin-audit-filters"><label>Busca<input id="audit-search" placeholder="Evento, recurso ou descrição"></label><label>Período<select id="audit-period"><option value="">Todo período</option><option value="today">Hoje</option></select></label><label>Usuário<select id="audit-user"><option value="">Todos</option>${[...new Set(audit.map(x=>x.actor))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Perfil<select id="audit-role"><option value="">Todos</option>${roles.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Evento<select id="audit-action"><option value="">Todos</option>${[...new Set(audit.map(x=>x.action))].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Vertical<select id="audit-vertical"><option value="">Todas</option>${scopes.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select></label><label>Resultado<select id="audit-result"><option value="">Todos</option><option>SUCESSO</option><option>NEGADO</option></select></label></div><div class="admin-users-table-wrap"><table class="data-table admin-audit-table"><thead><tr><th>Data/hora</th><th>Usuário</th><th>Perfil</th><th>Evento</th><th>Recurso</th><th>Descrição</th><th>Resultado</th></tr></thead><tbody id="admin-audit-body"></tbody></table><div id="admin-audit-empty" class="audit-empty" hidden>Nenhum evento encontrado.</div></div></section><div id="admin-governance-modal"></div>`;const draw=()=>{const q=document.getElementById('audit-search').value.toLowerCase(),period=document.getElementById('audit-period').value,user=document.getElementById('audit-user').value,role=document.getElementById('audit-role').value,action=document.getElementById('audit-action').value,vertical=document.getElementById('audit-vertical').value,result=document.getElementById('audit-result').value,today=new Date().toDateString();const list=audit.filter(x=>(!q||[x.action,x.resourceId,x.summary,x.actor].some(v=>String(v).toLowerCase().includes(q)))&&(!period||new Date(x.timestamp).toDateString()===today)&&(!user||x.actor===user)&&(!role||x.actorRole===role)&&(!action||x.action===action)&&(!vertical||x.serviceScope===vertical)&&(!result||x.result===result));const body=document.getElementById('admin-audit-body');body.innerHTML=list.map(x=>`<tr tabindex="0" data-event="${x.id}"><td>${esc(fmt(x.timestamp))}</td><td>${esc(x.actor)}</td><td>${esc(x.actorRole)}</td><td><strong>${esc(x.action)}</strong></td><td>${esc(x.resourceType)} · ${esc(x.resourceId)}</td><td>${esc(x.summary)}</td><td><span class="status-chip">${esc(x.result)}</span></td></tr>`).join('');document.getElementById('admin-audit-empty').hidden=list.length>0;body.querySelectorAll('tr').forEach(r=>{const open=()=>openAudit(r.dataset.event);r.addEventListener('click',open);r.addEventListener('keydown',e=>{if(e.key==='Enter'){open();}})});};['audit-search','audit-period','audit-user','audit-role','audit-action','audit-vertical','audit-result'].forEach(id=>document.getElementById(id).addEventListener(id==='audit-search'?'input':'change',draw));draw();}
  function openAudit(id){const x=audit.find(e=>e.id===id);modal(`<div class="modal-header"><div><h2 class="modal-title">Detalhe do evento</h2><p>${esc(x.id)}</p></div><button class="btn-icon" data-close>×</button></div><div class="admin-permission-body"><div class="admin-audit-detail">${[['Event ID',x.id],['Timestamp',fmt(x.timestamp)],['Actor',x.actor],['Role',x.actorRole],['Action',x.action],['Resource type',x.resourceType],['Resource ID',x.resourceId],['Resumo',x.summary],['Resultado',x.result]].map(a=>`<div><span>${a[0]}</span><strong>${esc(a[1])}</strong></div>`).join('')}</div><div class="admin-audit-changes"><section><h3>Antes</h3><pre>${esc(JSON.stringify(x.before,null,2)||'Não se aplica')}</pre></section><section><h3>Depois</h3><pre>${esc(JSON.stringify(x.after,null,2)||'Não se aplica')}</pre></section></div><p class="admin-source-note">Trilha demonstrativa imutável. Tokens e segredos não são exibidos.</p></div><div class="modal-footer"><button class="btn btn-secondary" data-close>Fechar</button></div>`);}
  function renderConfig(){view().innerHTML=shell('Configurações','Preferências locais da demonstração.')+`<section class="panel"><div class="panel-header"><h2 class="panel-title">Preferências</h2></div><div class="panel-body settings-list"><div class="setting-row"><div class="setting-copy"><strong>Tema</strong><span>Aparência atual</span></div><button class="btn btn-secondary" id="gov-theme">Alternar tema</button></div><div class="setting-row"><div class="setting-copy"><strong>Menu lateral</strong><span>Expandido ou compacto</span></div><button class="btn btn-secondary" id="gov-sidebar">Alternar menu</button></div></div></section>`;document.getElementById('gov-theme').addEventListener('click',window.toggleTheme);document.getElementById('gov-sidebar').addEventListener('click',window.toggleSidebarCollapse);}
  async function loadUsers(){users=(await CS360API.getAdminUsers()).data||[];}async function loadAudit(){audit=(await CS360API.getAdminAudit()).data||[];}
  async function route(){try{if(location.hash==='#auditoria'){await loadAudit();renderAudit();}else if(location.hash==='#configuracoes')renderConfig();else{await loadUsers();renderUsers();}}catch(e){error(e.message||'Erro ao carregar administração.');}}
  function init(){if(document.body.dataset.page!=='administracao-secondary')return;setTimeout(route,20);window.addEventListener('hashchange',route);}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
